-- GenDB engine variant Q06-between_expansion: template q06.sql, kind between_expansion (generated by generate.py; frozen)
SELECT
  SUM(l_extendedprice * l_discount) AS revenue
FROM lineitem
WHERE
  l_shipdate >= $1
  AND l_shipdate < $1 + INTERVAL '1 YEAR'
  AND l_discount >= $2 - 0.01
  AND l_discount <= $2 + 0.01
  AND l_quantity < $3
